const networkOptions=[{name:'Facebook',symbol:'f',color:'#3274cf',type:'Page'},{name:'Instagram',symbol:'◎',color:'#bf64a0',type:'Professional account'},{name:'Bluesky',symbol:'B',color:'#498bdc',type:'Account'},{name:'LinkedIn',symbol:'in',color:'#3d7ca2',type:'Organization page'},{name:'YouTube',symbol:'▶',color:'#c65b58',type:'Channel'},{name:'X',symbol:'𝕏',color:'#394237',type:'Account'}];
const assetKey='ngyn-asset-groups-v1';
let assetsData;try{assetsData=JSON.parse(localStorage.getItem(assetKey))||null}catch{}
if(!assetsData)assetsData={groups:groupNames.map((name,i)=>({id:'asset-'+i,name:'Harbourview '+name,brand:i===0?'Municipality of Harbourview':'Harbourview '+name,voice:i===0?'Clear, approachable, calm and inclusive. Use plain language.':'Helpful, practical and respectful. Explain services clearly.',direction:i===0?'Keep residents informed about civic services, council decisions and community updates.':'Share timely '+name.toLowerCase()+' updates. Prioritize useful information and accessible content.',color:['#d0fc70','#a4b8da','#9fcabf','#d5ba8e','#b7a3d4','#c4ccaa'][i]})),channels:groupData.channels.map((c,i)=>({...c,id:'social-'+i,assetGroup:'asset-'+i%6,art:i%6})),selected:'asset-0'};
let assetTab='channels';
function syncAssetResources(){socialResources.splice(0,socialResources.length,...assetsData.channels.map(c=>({id:c.id,name:c.name,detail:c.network+' · '+(assetsData.groups.find(g=>g.id===c.assetGroup)?.name||'Unassigned')})))}
function persistAssets(){localStorage.setItem(assetKey,JSON.stringify(assetsData));syncAssetResources()}
syncAssetResources();
// Original fictional profile artwork. No external image requests or real identities.
function profileArt(index){const colors=['#c5dc94','#8db8ca','#d6b789','#a5c5b5','#baa6ce','#c2cba5'];const bg=colors[index%6];const patterns=[`<path d="M0 60 25 32 44 48 65 20 90 48 100 40V100H0Z" fill="#334c38"/><path d="M0 77q25-14 50 0t50 0v23H0Z" fill="#7eaaa0"/><circle cx="28" cy="23" r="10" fill="#f6f2d9"/>`,`<path d="M10 70h80v6H10z M20 65V40h12v25m9 0V40h14v25m11 0V40h13v25M15 35 50 15 85 35Z" fill="#334539"/><path d="M10 82h80" stroke="#e9efd9" stroke-width="5"/>`,`<path d="M10 70q25-45 80 0" fill="none" stroke="#4a6554" stroke-width="8"/><path d="M0 76h100M0 88h100" stroke="#f4eddb" stroke-width="4"/><circle cx="50" cy="33" r="15" fill="#f4eddb"/>`,`<path d="M48 94V30" stroke="#4b6545" stroke-width="7"/><circle cx="50" cy="34" r="25" fill="#42684c"/><circle cx="27" cy="49" r="20" fill="#628b55"/><circle cx="72" cy="48" r="20" fill="#7da568"/>`,`<path d="M20 72V29q0-9 10-9h40q10 0 10 9v43Z" fill="#424f49"/><path d="M27 31h46v23H27z" fill="#e2ecd6"/><circle cx="33" cy="64" r="5" fill="#d8e7c6"/><circle cx="67" cy="64" r="5" fill="#d8e7c6"/><path d="M28 72v10m44-10v10" stroke="#424f49" stroke-width="7"/>`,`<path d="M0 70q50-35 100 0v30H0Z" fill="#52694c"/><path d="M50 24v45M24 46h52" stroke="#edf3dd" stroke-width="9"/><circle cx="50" cy="47" r="32" fill="none" stroke="#edf3dd" stroke-width="3"/>`];const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100"><rect width="100" height="100" fill="${bg}"/>${patterns[index%6]}</svg>`;return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}
function channelAvatar(c,size=''){const n=networkOptions.find(n=>n.name===c.network)||networkOptions[0];return `<span class="channel-avatar ${size}"><img src="${profileArt(c.art||0)}" alt="Fictional ${safe(c.name)} profile artwork"><span class="network-overlay" style="background:${n.color}" title="${n.name}">${n.symbol}</span></span>`}
function installAssetNav(){const old=document.querySelector('#groups-nav');if(old){old.innerHTML='<span class="ico"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 7h7l2 3h9v11H3z M3 7V3h7l2 3h9v4"/></svg></span>Asset groups';old.onclick=showAssetGroups}installAccountPicker()}
function showAssetGroups(){installAssetNav();document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));document.querySelector('#groups-nav').classList.add('active');document.querySelector('.crumb strong').textContent='Asset groups';const g=assetsData.groups.find(g=>g.id===assetsData.selected)||assetsData.groups[0];assetsData.selected=g.id;const channels=assetsData.channels.filter(c=>c.assetGroup===g.id);document.querySelector('#main').innerHTML=`<div class="page-head groups-heading"><div><div class="eyebrow">WORKSPACE / ASSETS</div><h2>Asset groups</h2><p>Your channels, one brand. Set a shared voice and direction for each group.</p></div><button class="btn" id="new-asset-group">＋ Create asset group</button></div><div class="asset-layout"><aside class="asset-picker"><div class="eyebrow">ASSET GROUPS</div>${assetsData.groups.map(x=>`<button class="${x.id===g.id?'selected':''}" data-asset="${x.id}"><span class="asset-color" style="background:${x.color}"></span><span>${safe(x.name.replace('Harbourview ',''))}</span><small>${assetsData.channels.filter(c=>c.assetGroup===x.id).length}</small></button>`).join('')}<p>Group channels by brand, service or campaign. User permissions are assigned separately.</p></aside><section class="asset-panel"><div class="asset-header"><img class="asset-cover-avatar" src="${profileArt(assetsData.groups.indexOf(g))}" alt="Fictional group artwork"><div class="grow"><h3>${safe(g.name)}</h3><p>${channels.length} social channels · 0 ad accounts</p></div><span class="badge ok">Fictional workspace</span></div><div class="asset-tabs"><button class="${assetTab==='channels'?'active':''}" data-asset-tab="channels">Social channels <span>${channels.length}</span></button><button class="${assetTab==='brand'?'active':''}" data-asset-tab="brand">Brand & direction</button><button class="${assetTab==='ads'?'active':''}" data-asset-tab="ads">Ad accounts <span>Later</span></button></div><div class="asset-body">${assetTab==='channels'?`<div class="asset-section-title"><div><h3>Social channels</h3><p>Manage the accounts that share this group’s brand and voice.</p></div><button class="btn primary" id="connect-social">＋ Add social channel</button></div><div class="channel-card-grid">${channels.map(c=>`<article class="social-card">${channelAvatar(c,'large')}<div class="social-card-text"><h4>${safe(c.name)}</h4><p>${c.network} · ${networkOptions.find(n=>n.name===c.network)?.type||'Account'}</p></div><span class="badge warn">Demo connection</span><div class="social-card-footer"><span>${c.network==='X'?'API access & commercial terms unverified':'API capabilities unverified'}</span><button class="asset-link" data-channel-details="${c.id}">Details →</button></div></article>`).join('')||'<div class="asset-empty"><h3>No channels yet</h3><p>Add your first channel to this asset group.</p></div>'}</div><div class="asset-footnote">Profile artwork and accounts are fictional. Adding a demo channel does not connect a real social account.</div>`:assetTab==='brand'?`<form id="brand-form"><div class="asset-section-title"><div><h3>Brand & direction</h3><p>A shared brief for content created for this asset group.</p></div><button class="btn primary" type="submit">Save changes</button></div><div class="field"><label for="brand-name">Brand name</label><input id="brand-name" required value="${safe(g.brand)}"></div><div class="field"><label for="brand-voice">Voice & tone</label><textarea id="brand-voice" rows="3" placeholder="How should this brand sound?">${safe(g.voice)}</textarea></div><div class="field"><label for="brand-direction">Content direction</label><textarea id="brand-direction" rows="4" placeholder="Goals, audience and what to prioritize">${safe(g.direction)}</textarea></div><p class="asset-footnote">This is saved guidance for future drafts. It does not generate or publish content automatically.</p></form>`:'<div class="asset-empty"><div class="ad-placeholder">＋</div><h3>Ad accounts will live here</h3><p>Keep paid and organic accounts under the same brand.<br>Ad-account setup is planned for a later step.</p><span class="badge">No advertising spend enabled</span></div>'}</div></section></div>`;document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{assetsData.selected=b.dataset.asset;persistAssets();showAssetGroups()});document.querySelectorAll('[data-asset-tab]').forEach(b=>b.onclick=()=>{assetTab=b.dataset.assetTab;showAssetGroups()});document.querySelector('#new-asset-group').onclick=newAssetGroup;document.querySelector('#connect-social')?.addEventListener('click',connectSocial);document.querySelector('#brand-form')?.addEventListener('submit',e=>{e.preventDefault();g.brand=document.querySelector('#brand-name').value.trim();g.voice=document.querySelector('#brand-voice').value.trim();g.direction=document.querySelector('#brand-direction').value.trim();persistAssets();toast('Brand, voice and content direction saved.')});document.querySelectorAll('[data-channel-details]').forEach(b=>b.onclick=()=>{const c=assetsData.channels.find(c=>c.id===b.dataset.channelDetails);modal(`<div class="modal-head"><h2>${safe(c.name)}</h2><button data-close aria-label="Close">×</button></div><div class="channel-detail-head">${channelAvatar(c,'large')}<div><strong>${c.network}</strong><p>Demo connection · ${safe(g.name)}</p></div></div><p class="form-description">Fictional account. Authentication, media publishing, comments, messaging, analytics, rate limits and platform approvals have not been verified. No tokens or credentials are stored.</p><p class="permission-hint">Only explicitly assigned users can access this account. Asset-group membership grants no access.</p>`)});}
function assetModal(title,body){modal(`<div class="modal-head"><div><div class="eyebrow">ASSET GROUPS</div><h2>${title}</h2></div><button data-close aria-label="Close">×</button></div>${body}`);const b=document.querySelector('.modal-box');b.classList.add('asset-dialog');b.setAttribute('role','dialog');b.setAttribute('aria-modal','true');b.setAttribute('aria-label',title)}
function newAssetGroup(){assetModal('Create asset group',`<p class="form-description">Start with a name. Add channels and define the brand when you’re ready.</p><form id="new-asset-form"><div class="field"><label for="asset-name">Asset group name</label><input id="asset-name" required maxlength="100" placeholder="e.g. Harbourview Public Safety"></div><p id="asset-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Create group</button></div></form>`);document.querySelector('#asset-name').focus();document.querySelector('#new-asset-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#asset-name').value.trim();if(!name)return;if(assetsData.groups.some(g=>g.name.toLowerCase()===name.toLowerCase())){document.querySelector('#asset-error').textContent='An asset group with this name already exists.';return}const g={id:crypto.randomUUID(),name,brand:name,voice:'',direction:'',color:'#d0fc70'};assetsData.groups.push(g);assetsData.selected=g.id;assetTab='channels';persistAssets();close();showAssetGroups();toast('Asset group created. No accounts or user access added.')}}
function connectSocial(){assetModal('Add social channel',`<p class="form-description">Choose a network for <strong>${safe(assetsData.groups.find(g=>g.id===assetsData.selected).name)}</strong>.</p><div class="connect-grid">${networkOptions.map(n=>`<button data-connect="${n.name}"><span style="background:${n.color}">${n.symbol}</span> Add ${n.name}</button>`).join('')}</div><div class="connection-boundary"><strong>Demo connections</strong><p>All six networks are available to mock. Production support is unverified; X also requires review of commercial API terms.</p></div>`);document.querySelectorAll('[data-connect]').forEach(b=>b.onclick=()=>configureChannel(b.dataset.connect))}
function configureChannel(network){const g=assetsData.groups.find(g=>g.id===assetsData.selected);let art=assetsData.groups.indexOf(g)%6;assetModal('Add '+network,`<form id="channel-setup"><p class="form-description">Create a fictional ${network} account in <strong>${safe(g.name)}</strong>.</p><div class="channel-setup-preview"><span id="chosen-art">${channelAvatar({name:g.name,network,art},'large')}</span><div><strong>Profile image</strong><p>Choose a sample illustration</p><div class="art-options">${Array.from({length:6},(_,i)=>`<button type="button" data-art="${i}" class="${i===art?'selected':''}" aria-label="Choose sample artwork ${i+1}"><img src="${profileArt(i)}" alt="Sample artwork ${i+1}"></button>`).join('')}</div></div></div><div class="field"><label for="social-account-name">Account display name</label><input id="social-account-name" required maxlength="100" value="${safe(g.name)}" autocomplete="off"></div><div class="field"><label for="social-asset-group">Asset group</label><select id="social-asset-group">${assetsData.groups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select></div><div class="connection-boundary"><strong>No real connection will be made</strong><p>No login, OAuth flow, password or token is required. New channels grant no user access automatically.</p></div><p id="channel-setup-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" id="back-networks">← Networks</button><button class="btn primary" type="submit">Add demo channel</button></div></form>`);document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{art=Number(b.dataset.art);document.querySelectorAll('[data-art]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelector('#chosen-art').innerHTML=channelAvatar({name:g.name,network,art},'large')});document.querySelector('#back-networks').onclick=connectSocial;document.querySelector('#social-account-name').focus();document.querySelector('#channel-setup').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#social-account-name').value.trim(),assetGroup=document.querySelector('#social-asset-group').value;if(!name)return;if(assetsData.channels.some(c=>c.name.toLowerCase()===name.toLowerCase()&&c.network===network)){document.querySelector('#channel-setup-error').textContent='That demo account already exists on this network.';return}assetsData.channels.push({id:crypto.randomUUID(),name,network,assetGroup,art});assetsData.selected=assetGroup;assetTab='channels';persistAssets();close();showAssetGroups();installAccountPicker(true);toast(`${network} demo channel added. Assign user access separately.`)}}
function installAccountPicker(refresh=false){const select=document.querySelector('#account');if(!select)return;if(document.querySelector('#visual-account-picker')&&!refresh)return;document.querySelector('#visual-account-picker')?.remove();select.classList.add('hidden');const wrapper=document.createElement('div');wrapper.id='visual-account-picker';wrapper.className='visual-account-picker';wrapper.innerHTML=`<button class="account-picker-button" id="account-picker-toggle" aria-expanded="false" aria-controls="account-picker-menu"><span class="avatar-stack">${assetsData.channels.slice(0,3).map(c=>channelAvatar(c)).join('')}</span><span>All channels (${assetsData.channels.length})</span><span>⌄</span></button><div class="account-picker-menu hidden" id="account-picker-menu"><input placeholder="Search channels…" aria-label="Search channels"><div class="account-picker-actions"><button id="picker-create-group">＋ Asset group</button><button id="picker-add-social">＋ Social channel</button></div><div class="picker-accounts">${assetsData.channels.map(c=>`<label data-picker-name="${safe(c.name.toLowerCase())}"><input type="checkbox" checked value="${c.id}">${channelAvatar(c)}<span>${safe(c.name)}<small>${c.network}</small></span></label>`).join('')}</div><div class="picker-bottom"><span>Demo selector</span><button id="picker-all">Select all</button></div></div>`;select.insertAdjacentElement('afterend',wrapper);const toggle=document.querySelector('#account-picker-toggle'),menu=document.querySelector('#account-picker-menu');toggle.onclick=()=>{menu.classList.toggle('hidden');toggle.setAttribute('aria-expanded',String(!menu.classList.contains('hidden')))};document.querySelector('#picker-create-group').onclick=()=>{menu.classList.add('hidden');showAssetGroups();newAssetGroup()};document.querySelector('#picker-add-social').onclick=()=>{menu.classList.add('hidden');showAssetGroups();connectSocial()};menu.querySelector('input[aria-label]').oninput=e=>menu.querySelectorAll('[data-picker-name]').forEach(l=>l.hidden=!l.dataset.pickerName.includes(e.target.value.toLowerCase()));const count=()=>{const total=menu.querySelectorAll('.picker-accounts input:checked').length;toggle.querySelector(':scope>span:nth-child(2)').textContent=total===assetsData.channels.length?`All channels (${total})`:`${total} channels selected`;};menu.querySelectorAll('.picker-accounts input').forEach(c=>c.onchange=count);document.querySelector('#picker-all').onclick=()=>{menu.querySelectorAll('.picker-accounts input').forEach(c=>c.checked=true);count()}}
document.addEventListener('click',e=>{if(!e.target.closest('#visual-account-picker')){document.querySelector('#account-picker-menu')?.classList.add('hidden');document.querySelector('#account-picker-toggle')?.setAttribute('aria-expanded','false')}},true);
const renderBeforeAssets=render;render=function(){renderBeforeAssets();installAssetNav()};
installAssetNav();showAssetGroups();
